-- ══════════════════════════════════════════════════════════
--  장비 데이터 넣기 — 03-equipment.sql 을 먼저 실행하세요.
--  장비 112개 · 치수 111개  (엑셀에서 생성)
--  여러 번 실행해도 안전합니다 (같은 자산번호는 덮어씀).
-- ══════════════════════════════════════════════════════════

on conflict (id) do update set
  nick = excluded.nick,
  cat = excluded.cat,
  cat_label = excluded.cat_label,
  sub = excluded.sub,
  product = excluded.product,
  brand = excluded.brand,
  model = excluded.model,
  serial = excluded.serial,
  status = excluded.status,
  location = excluded.location,
  image_url = excluded.image_url,
  purchased_on = excluded.purchased_on,
  vendor = excluded.vendor,
  price = excluded.price,
  checked_on = excluded.checked_on,
  check_cycle = excluded.check_cycle,
  next_check = excluded.next_check,
  note = excluded.note,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  w = excluded.w,
  d = excluded.d,
  h = excluded.h,
  h_min = excluded.h_min,
  h_max = excluded.h_max,
  default_h = excluded.default_h,
  src = excluded.src,
  rule = excluded.rule,
  basis = excluded.basis;

-- 확인
select (select count(*) from public.gear_equipment) as "장비",
       (select count(*) from public.gear_specs) as "치수",
       (select count(*) from public.gear_equipment where status='정상') as "정상",
       (select count(*) from public.gear_equipment where nick is not null) as "별칭있음";